    discriminant = b * b - 4 * c
    answer = 'Yes' if sympy.sqrt(discriminant).is_integer else 'No'
    check = 'Yes' if discriminant > 0 and (discriminant ** 0.5).is_integer else 'No'
    parameters = {'b': b, 'c': c}
    return (parameters, answer, check)



